input.command:
KEY=$(grep "MYLYNX_API_KEY" ~/.dsh/.credentials.yaml | sed -E 's/.*:[[:space:]]*//; s/["'"'"']//g'); ids=$(curl -s --max-time 30 http://localhost:20128/v1/models -H "Authorization: Bearer $KEY" | python -c "
import json,sys; d=json.load(sys.stdin)
for m in d['data']:
  i=m.get('id') or ''
  if 'qwen3-coder' in i.lower() and not i.startswith(('kiro/','kr/')): print(i)"); echo "$ids"; echo ---
for m in $(echo "$ids" | head -8); do r=$(curl -s -w "|%{http_code}" --max-time 60 http://localhost:20128/v1/messages -H "Authorization: Bearer $KEY" -H "anthropic-version: 2023-06-01" -H "content-type: application/json" -d "{\"model\":\"$m\",\"max_tokens\":5,\"messages\":[{\"role\":\"user\",\"content\":\"hi\"}]}"); echo "$m -> ${r##*|} ${r:0:120}"; done
